// In-memory / Adapter helper functions
export function getAllBooks(): IBook[] {
  return initialBooks;
}

export function getBookById(productId: string): IBook | undefined {
  return initialBooks.find((b) => b.productId === productId || b.slug === productId);
}

export function getBooksByCategory(categorySlug: string): IBook[] {
  return initialBooks.filter((b) => b.category === categorySlug);
}

export function getAllBookCategories(): IBookCategory[] {
  return bookCategories.map((cat) => ({
    ...cat,
    count: initialBooks.filter((b) => b.category === cat.slug).length,
  }));
}

export function getCategoryBySlug(slug: string): IBookCategory | undefined {
  return bookCategories.find((c) => c.slug === slug);
}
